  stack(640,194,["第二个想法：你「一次拿到两个观测」","⇒ 然后由你来说「哪一个更好」","⭐ 这个叫做 pairwise preference data（成对偏好数据）","⇒ 而它「容易得多」"],740,32,6);
  note("★★ 注意讲者给的理由只有一个词：easier（更容易）—— 不是更准、不是信息更多",640,356,"r");
